];

export function morphHexToRgb(hex: string): [number, number, number] {
  let h = (hex || '#000000').replace('#', '');
  if (h.length === 3) {
    h = h
      .split('')
      .map((c) => c + c)
      .join('');
  }
  const n = Number.parseInt(h, 16);
  return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255];
}

import type { MorphEaseFn } from './types';

const linear: MorphEaseFn = (t) => t;

const BASE_IN: Record<string, MorphEaseFn> = {
  power0: linear,
  linear,
  none: linear,
  power1: (t) => t * t,
  quad: (t) => t * t,
  power2: (t) => t * t * t,
  cubic: (t) => t * t * t,
  power3: (t) => t ** 4,
  quart: (t) => t ** 4,
  power4: (t) => t ** 5,
  quint: (t) => t ** 5,
  strong: (t) => t ** 5,
  sine: (t) => 1 - Math.cos((t * Math.PI) / 2),
  expo: (t) => (t === 0 ? 0 : 2 ** (10 * (t - 1))),
  circ: (t) => 1 - Math.sqrt(1 - t * t),
};

/**
 * Resolves a GSAP-style ease name ("power2.inOut", "expo.out", "none")
 * into an easing function. Unknown names fall back to GSAP's default
 * "power1.out".
 */
export function resolveEase(name: string): MorphEaseFn {
  const [rawBase = 'power1', rawType = 'out'] = name.trim().split('.');
  const base = BASE_IN[rawBase.toLowerCase()];
  if (!base) return resolveEase('power1.out');
  if (base === linear) return linear;
  const type = rawType.toLowerCase();
  if (type === 'in') return base;
  if (type === 'inout') {
    return (t) => (t < 0.5 ? base(t * 2) / 2 : 1 - base((1 - t) * 2) / 2);
  }
  return (t) => 1 - base(1 - t);
}

import { Renderer, Triangle, Program, Mesh, Texture } from 'ogl';
import type { OGLRenderingContext } from 'ogl';
import { MORPH_FRAGMENT, MORPH_VERTEX } from './morph-shaders';
import { MORPH_TRANSITIONS, morphHexToRgb } from './morph-defaults';
import { resolveEase } from './morph-ease';
import type {
  MorphEngineConfig,
  MorphEngineOptions,
  MorphItem,
  MorphTween,
} from './types';

function makeFallbackTexture(gl: OGLRenderingContext): Texture {
  const size = 4;
  const data = new Uint8Array(size * size * 4);
  for (let i = 0; i < size * size; i++) {
    data[i * 4] = 24;
    data[i * 4 + 1] = 24;
    data[i * 4 + 2] = 28;
    data[i * 4 + 3] = 255;
  }
  return new Texture(gl, {
    image: data,
    width: size,
    height: size,
    generateMipmaps: false,
  });
}

export class MorphEngine {
  private container: HTMLElement;
  private items: MorphItem[];
  private getOptions: () => MorphEngineOptions;
  private onIndexChange: (index: number) => void;
  private reducedMotion: boolean;

  private current: number;
  private animating = false;
  private dragging = false;
  private dragDir = 0;
  private shownIndex: number;
  private progress = 0;
  private tween: MorphTween | null = null;

  private renderer: Renderer;
  private gl: OGLRenderingContext;
  private canvas: HTMLCanvasElement;
  private program: Program;
  private mesh: Mesh;
  private textures: Texture[];
  private sizes: [number, number][];
  private images: HTMLImageElement[] = [];
  private resizeObserver: ResizeObserver;
  private raf = 0;
  private lastT = -1;
  private running = false;
  private destroyed = false;

  constructor(container: HTMLElement, config: MorphEngineConfig) {
    this.container = container;
    this.items = config.items;
    this.getOptions = config.getOptions;
    this.onIndexChange = config.onIndexChange;
    this.reducedMotion = config.reducedMotion;
    this.current = config.startIndex;
    this.shownIndex = config.startIndex;

    this.renderer = new Renderer({
      alpha: false,
      antialias: true,
      dpr: Math.min(window.devicePixelRatio || 1, config.dprCap),
    });
    this.gl = this.renderer.gl;
    this.gl.clearColor(0.05, 0.05, 0.06, 1);

    this.canvas = this.gl.canvas;
    this.canvas.style.display = 'block';
    this.canvas.style.width = '100%';
    this.canvas.style.height = '100%';
    container.appendChild(this.canvas);

    this.textures = this.items.map(() => makeFallbackTexture(this.gl));
    this.sizes = this.items.map((): [number, number] => [1, 1]);

    const opts = this.getOptions();
    this.program = new Program(this.gl, {
      vertex: MORPH_VERTEX,
      fragment: MORPH_FRAGMENT,
      uniforms: {
        tCurrent: { value: this.textures[this.current] },
        tNext: { value: this.textures[this.current] },
        uResolution: { value: [1, 1] },
        uCurrentSize: { value: this.sizes[this.current] },
        uNextSize: { value: this.sizes[this.current] },
        uProgress: { value: 0 },
        uDir: { value: 1 },
        uMode: { value: MORPH_TRANSITIONS[opts.transition] ?? 0 },
        uIntensity: { value: opts.intensity },
        uScale: { value: opts.scale },
        uAberration: { value: opts.aberration },
        uDrift: { value: opts.drift },
        uTime: { value: 0 },
        uReduce: { value: this.reducedMotion ? 1 : 0 },
        uPointer: { value: [0.5, 0.5] },
        uOverlay: { value: morphHexToRgb(opts.overlayColor) },
      },
    });

    this.mesh = new Mesh(this.gl, {
      geometry: new Triangle(this.gl),
      program: this.program,
    });

    this.canvas.addEventListener('webglcontextlost', this.onContextLost, false);

    this.resizeObserver = new ResizeObserver(() => this.resize());
    this.resizeObserver.observe(container);
    this.resize();

    this.loadTextures();
    this.setActive(true);
  }

  private loadTextures(): void {
    this.items.forEach((item, index) => {
      const img = new Image();
      img.crossOrigin = 'anonymous';
      img.decoding = 'async';
      img.onload = () => {
        if (this.destroyed) return;
        const texture = new Texture(this.gl, { generateMipmaps: false });
        texture.image = img;
        const old = this.textures[index];
        this.textures[index] = texture;
        this.sizes[index] = [img.naturalWidth || 1, img.naturalHeight || 1];
        const u = this.program.uniforms;
        if (u.tCurrent.value === old) {
          u.tCurrent.value = texture;
          u.uCurrentSize.value = this.sizes[index];
        }
        if (u.tNext.value === old) {
          u.tNext.value = texture;
          u.uNextSize.value = this.sizes[index];
        }
        if (old?.texture) this.gl.deleteTexture(old.texture);
      };
      img.src = item.image;
      this.images.push(img);
    });
  }

  private resize(): void {
    const rect = this.container.getBoundingClientRect();
    this.renderer.setSize(Math.max(rect.width, 1), Math.max(rect.height, 1));
    this.program.uniforms.uResolution.value = [
      this.gl.canvas.width,
      this.gl.canvas.height,
    ];
  }

  private syncOptions(): void {
    const opts = this.getOptions();
    const u = this.program.uniforms;
    u.uMode.value = MORPH_TRANSITIONS[opts.transition] ?? 0;
    u.uIntensity.value = opts.intensity;
    u.uScale.value = opts.scale;
    u.uAberration.value = opts.aberration;
    u.uDrift.value = opts.drift;
    u.uOverlay.value = morphHexToRgb(opts.overlayColor);
  }

  private loop = (t: number): void => {
    const dt = this.lastT < 0 ? 0 : Math.min((t - this.lastT) / 1000, 0.1);
    this.lastT = t;
    this.stepTween(dt);
    const u = this.program.uniforms;
    u.uTime.value = t * 0.001;
    u.uProgress.value = this.progress;
    if (!this.dragging && !this.animating) this.syncOptions();
    this.renderer.render({ scene: this.mesh });
    this.raf = requestAnimationFrame(this.loop);
  };

  private stepTween(dt: number): void {
    const tw = this.tween;
    if (!tw) return;
    tw.elapsed += dt;
    const k = tw.duration <= 0 ? 1 : Math.min(tw.elapsed / tw.duration, 1);
    this.progress = tw.from + (tw.to - tw.from) * tw.ease(k);
    if (k >= 1) {
      this.tween = null;
      tw.onComplete();
    }
  }

  private startTween(
    to: number,
    duration: number,
    ease: string,
    onComplete: () => void,
  ): void {
    this.tween = {
      from: this.progress,
      to,
      elapsed: 0,
      duration,
      ease: resolveEase(ease),
      onComplete,
    };
  }

  /** Pause/resume the render loop (used when the slider leaves the viewport). */
  setActive(active: boolean): void {
    if (this.destroyed || active === this.running) return;
    this.running = active;
    if (active) {
      this.lastT = -1;
      this.raf = requestAnimationFrame(this.loop);
    } else {
      cancelAnimationFrame(this.raf);
    }
  }

  setReducedMotion(reduce: boolean): void {
    this.reducedMotion = reduce;
    this.program.uniforms.uReduce.value = reduce ? 1 : 0;
  }

  private wrap(i: number): number {
    const n = this.items.length;
    return ((i % n) + n) % n;
  }

  private prepareNext(dir: number): number {
    const target = this.wrap(this.current + dir);
    const u = this.program.uniforms;
    u.tCurrent.value = this.textures[this.current];
    u.uCurrentSize.value = this.sizes[this.current];
    u.tNext.value = this.textures[target];
    u.uNextSize.value = this.sizes[target];
    u.uDir.value = dir;
    return target;
  }

  goTo(dir: number): void {
    if (this.animating || this.dragging || this.items.length < 2) return;
    const opts = this.getOptions();
    if (!opts.loop) {
      const raw = this.current + dir;
      if (raw < 0 || raw > this.items.length - 1) return;
    }
    this.syncOptions();
    const target = this.prepareNext(dir);
    this.animating = true;
    this.announce(target);
    const duration = this.reducedMotion
      ? Math.min(opts.duration, 0.4)
      : opts.duration;
    this.progress = 0;
    this.startTween(1, duration, opts.ease, () => this.commit(target));
  }

  private announce(index: number): void {
    if (index === this.shownIndex) return;
    this.shownIndex = index;
    this.onIndexChange(index);
  }

  private commit(target: number): void {
    this.current = target;
    const u = this.program.uniforms;
    u.tCurrent.value = this.textures[target];
    u.uCurrentSize.value = this.sizes[target];
    this.progress = 0;
    u.uProgress.value = 0;
    this.animating = false;
    this.announce(target);
  }

  next(): void {
    this.goTo(1);
  }

  prev(): void {
    this.goTo(-1);
  }

  setPointer(x: number, y: number): void {
    this.program.uniforms.uPointer.value = [x, y];
  }

  beginDrag(): boolean {
    if (this.animating || this.items.length < 2) return false;
    this.dragging = true;
    this.dragDir = 0;
    this.syncOptions();
    return true;
  }

  drag(ndx: number): void {
    if (!this.dragging) return;
    const opts = this.getOptions();
    const dir = ndx < 0 ? 1 : -1;
    if (!opts.loop) {
      const raw = this.current + dir;
      if (raw < 0 || raw > this.items.length - 1) {
        this.progress = 0;
        return;
      }
    }
    if (dir !== this.dragDir) {
      this.dragDir = dir;
      this.prepareNext(dir);
    }
    this.progress = Math.min(Math.abs(ndx), 1);
    this.announce(
      this.progress > 0.5 ? this.wrap(this.current + dir) : this.current,
    );
  }

  endDrag(): void {
    if (!this.dragging) return;
    this.dragging = false;
    if (this.dragDir === 0) return;
    const target = this.wrap(this.current + this.dragDir);
    const duration = this.reducedMotion ? 0.3 : 0.5;
    this.animating = true;
    if (this.progress > 0.4) {
      this.announce(target);
      this.startTween(1, duration, 'power2.out', () => this.commit(target));
    } else {
      this.announce(this.current);
      this.startTween(0, duration, 'power2.out', () => {
        this.animating = false;
      });
    }
  }

  private onContextLost = (e: Event): void => {
    e.preventDefault();
    cancelAnimationFrame(this.raf);
    this.running = false;
  };

  destroy(): void {
    this.destroyed = true;
    cancelAnimationFrame(this.raf);
    this.running = false;
    this.tween = null;
    this.resizeObserver.disconnect();
    this.canvas.removeEventListener('webglcontextlost', this.onContextLost);
    for (const img of this.images) {
      img.onload = null;
    }
    this.images = [];
    for (const tex of this.textures) {
      if (tex?.texture) this.gl.deleteTexture(tex.texture);
    }
    this.mesh.geometry.remove();
    this.program.remove();
    this.gl.getExtension('WEBGL_lose_context')?.loseContext();
    this.canvas.remove();
  }
}

export const MORPH_VERTEX = /* glsl */ `
attribute vec2 position;
attribute vec2 uv;
varying vec2 vUv;
void main() {
  vUv = uv;
  gl_Position = vec4(position, 0.0, 1.0);
}
`;

export const MORPH_FRAGMENT = /* glsl */ `
precision highp float;

uniform sampler2D tCurrent;
uniform sampler2D tNext;
uniform vec2 uResolution;
uniform vec2 uCurrentSize;
uniform vec2 uNextSize;
uniform float uProgress;
uniform float uDir;
uniform int uMode;
uniform float uIntensity;
uniform float uScale;
uniform float uAberration;
uniform float uDrift;
uniform float uTime;
uniform float uReduce;
uniform vec2 uPointer;
uniform vec3 uOverlay;

varying vec2 vUv;

const float PI = 3.14159265359;

float hash11(float p) {
  p = fract(p * 0.1031);
  p *= p + 33.33;
  p *= p + p;
  return fract(p);
}

float hash21(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  float a = hash21(i);
  float b = hash21(i + vec2(1.0, 0.0));
  float c = hash21(i + vec2(0.0, 1.0));
  float d = hash21(i + vec2(1.0, 1.0));
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

float fbm(vec2 p) {
  float v = 0.0;
  float a = 0.5;
  for (int i = 0; i < 5; i++) {
    v += a * noise(p);
    p *= 2.0;
    a *= 0.5;
  }
  return v;
}

mat2 rot(float a) {
  float s = sin(a);
  float c = cos(a);
  return mat2(c, -s, s, c);
}

vec2 coverUV(vec2 uv, vec2 res, vec2 img) {
  float rA = res.x / max(res.y, 1.0);
  float iA = img.x / max(img.y, 1.0);
  vec2 s = vec2(1.0);
  float ratio = rA / max(iA, 0.0001);
  if (ratio > 1.0) {
    s.y = 1.0 / ratio;
  } else {
    s.x = ratio;
  }
  return (uv - 0.5) * s + 0.5;
}

void main() {
  float p = clamp(uProgress, 0.0, 1.0);
  float env = sin(p * PI);

  vec2 uv = vUv;

  uv += vec2(sin(uTime * 0.25 + uv.y * 4.0), cos(uTime * 0.22 + uv.x * 4.0)) * uDrift * 0.008;
  uv = (uv - 0.5) * (1.0 - uDrift * 0.02 * sin(uTime * 0.4)) + 0.5;

  vec2 uvC = uv;
  vec2 uvN = uv;
  float m = smoothstep(0.0, 1.0, p);

  if (uReduce < 0.5) {
    if (uMode == 3) {
      vec2 c = uv - 0.5;
      float r = length(c);
      float ang = env * uIntensity * 3.5 * (1.0 - r);
      uvC = rot(ang) * c + 0.5;
      uvN = rot(-ang) * c + 0.5;
      m = smoothstep(0.0, 1.0, p);
    } else if (uMode == 1) {
      float d = distance(uv, uPointer);
      float ring = p * 1.6;
      float wave = sin((d - ring) * 30.0) * env;
      vec2 dir = normalize(uv - uPointer + 1e-4);
      vec2 disp = dir * wave * uIntensity * 0.25;
      uvC = uv + disp;
      uvN = uv + disp * 0.6;
      m = 1.0 - smoothstep(ring - 0.03, ring + 0.03, d);
    } else if (uMode == 2) {
      float slices = 14.0;
      float row = floor(uv.y * slices);
      float rnd = hash11(row);
      vec2 disp = vec2((rnd - 0.5) * env * uIntensity * 0.6, 0.0);
      uvC = uv + disp;
      uvN = uv + disp;
      float localX = uDir > 0.0 ? uv.x : 1.0 - uv.x;
      float th = p * 1.5 - 0.25 + (rnd - 0.5) * 0.25;
      m = 1.0 - smoothstep(th - 0.06, th + 0.06, localX);
    } else {
      float nn = fbm(uv * uScale + uTime * 0.03);
      float warp = fbm(uv * uScale * 1.7 - uTime * 0.02);
      vec2 g = vec2(nn, warp) - 0.5;
      uvC = uv + g * uIntensity * 0.5 * p;
      uvN = uv - g * uIntensity * 0.5 * (1.0 - p);
      m = smoothstep(nn - 0.15, nn + 0.15, p);
    }
  }

  vec2 sC = coverUV(uvC, uResolution, uCurrentSize);
  vec2 sN = coverUV(uvN, uResolution, uNextSize);

  float ca = uReduce < 0.5 ? uAberration * env * 0.03 : 0.0;

  vec3 colC = vec3(
    texture2D(tCurrent, sC + vec2(ca, 0.0)).r,
    texture2D(tCurrent, sC).g,
    texture2D(tCurrent, sC - vec2(ca, 0.0)).b
  );
  vec3 colN = vec3(
    texture2D(tNext, sN + vec2(ca, 0.0)).r,
    texture2D(tNext, sN).g,
    texture2D(tNext, sN - vec2(ca, 0.0)).b
  );

  vec3 col = mix(colC, colN, m);

  float vig = smoothstep(1.25, 0.25, length(uv - 0.5));
  col = mix(col, uOverlay, (1.0 - vig) * 0.28);

  gl_FragColor = vec4(col, 1.0);
}
`;

export type MorphTransition = 'melt' | 'ripple' | 'shear' | 'swirl';

export interface MorphItem {
  image: string;
  caption?: string;
}

export interface MorphSliderProps {
  items?: MorphItem[];
  startIndex?: number;
  transition?: MorphTransition;
  duration?: number;
  ease?: string;
  intensity?: number;
  scale?: number;
  aberration?: number;
  drift?: number;
  autoplay?: boolean;
  autoplayDelay?: number;
  loop?: boolean;
  radius?: number;
  overlayColor?: string;
  showCaptions?: boolean;
  showControls?: boolean;
  showIndicators?: boolean;
  class?: string;
}

export interface MorphEngineOptions {
  transition: MorphTransition;
  duration: number;
  ease: string;
  intensity: number;
  scale: number;
  aberration: number;
  drift: number;
  overlayColor: string;
  loop: boolean;
}

export interface MorphEngineConfig {
  items: MorphItem[];
  startIndex: number;
  reducedMotion: boolean;
  getOptions: () => MorphEngineOptions;
  onIndexChange: (index: number) => void;
  dprCap: number;
}

export type MorphEaseFn = (t: number) => number;

export interface MorphTween {
  from: number;
  to: number;
  elapsed: number;
  duration: number;
  ease: MorphEaseFn;
  onComplete: () => void;
}
